def flatten(d: dict) -> dict:
    """
    Flattens one level of nested dictionaries, joining keys with a dot.

    Example: {"a": {"b": 1}} -> {"a.b": 1}
    Non-dict values stay as they are: {"c": 2} -> {"c": 2
    """
    flattened = {}
    for key, value in d.items():
        if isinstance(value, dict):
            # If the value is a dictionary, flatten it recursively (or handle one level)
            # For this specific requirement (one level deep), we iterate through its items:
            for sub_key, sub_value in value.items():
                new_key = f"{key}.{sub_key}"
                flattened[new_key] = sub_value
        else:
            # If the value is not a dictionary, keep it as is (though for one level deep flattening, 
            # this case only applies to top-level non-dict values)
            flattened[key] = value
    return flattened
